WITH objects AS (SELECT f.classid, f.objid FROM ROWS FROM (pg_catalog.unnest($1::pg_catalog.oid[]) , pg_catalog.unnest($2::pg_catalog.oid[]) ) f(classid, objid)) SELECT d.tableoid::pg_catalog.oid::pg_catalog.text AS catalog_class_oid, pg_catalog.to_jsonb(d)::pg_catalog.text AS original_catalog_row_json FROM pg_catalog.pg_shdescription d WHERE EXISTS (SELECT 1 FROM objects f WHERE f.classid = d.classoid AND f.objid = d.objoid) ORDER BY d.classoid, d.objoid